// Store page context and prepare for HTTP fetch
const item = $input.item.json;
return [{ json: {
  page_id: item.id,
  url: item.url,
  domain_id: item.domain_id,
  domain: item.domain
}}];

// Process HTTP response and extract links
// Get page context from Prep Fetch node
let pageContext;
try {
  pageContext = $('Prep Fetch').first().json;
} catch (e) {
  pageContext = { page_id: '', url: '', domain_id: '', domain: '' };
}

const url = pageContext.url || '';
const domain_id = pageContext.domain_id || '';
const domain = pageContext.domain || '';
const page_id = pageContext.page_id || '';

// Get HTTP response
const httpResponse = $input.item.json;
let html = '';
let status = 200;

// Handle different response formats
if (typeof httpResponse === 'string') {
  html = httpResponse;
} else if (httpResponse && httpResponse.data && typeof httpResponse.data === 'string') {
  html = httpResponse.data;
} else if (httpResponse && typeof httpResponse === 'object') {
  // Try to find HTML in the response
  const str = JSON.stringify(httpResponse);
  if (str.length > 100 && (str.includes('<html') || str.includes('<!DOCTYPE') || str.includes('<body'))) {
    // Response might be the HTML directly parsed as object (unlikely but check)
    html = '';
  }
}

// If no HTML found, mark as failed
if (!html || html.length < 100) {
  return [{ json: {
    page_id, url, domain_id, domain,
    success: false,
    status: 0,
    discovered_urls: []
  }}];
}

// Extract title
let title = '';
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
if (titleMatch) title = titleMatch[1].trim();

// Extract all internal links
const discovered_urls = [];
const linkPattern = /href=["']([^"']+)["']/gi;
let match;

while ((match = linkPattern.exec(html)) !== null) {
  let href = match[1].trim();

  // Skip non-http, anchors, javascript, etc.
  if (href.startsWith('#') || href.startsWith('javascript:') || href.startsWith('mailto:') || href.startsWith('tel:')) {
    continue;
  }

  // Make relative URLs absolute
  if (href.startsWith('/') && !href.startsWith('//')) {
    href = `https://${domain}${href}`;
  } else if (!href.startsWith('http')) {
    continue;
  }

  // Only include links to the same domain
  try {
    const urlObj = new URL(href);
    const hrefDomain = urlObj.hostname.replace('www.', '');
    if (hrefDomain === domain || hrefDomain.endsWith('.' + domain)) {
      const cleanUrl = urlObj.origin + urlObj.pathname;

      // Skip non-content files
      if (!cleanUrl.match(/\.(jpg|jpeg|png|gif|webp|svg|ico|pdf|css|js|xml|json|woff|woff2|ttf|eot)$/i)) {
        discovered_urls.push(cleanUrl);
      }
    }
  } catch (e) {}
}

// Dedupe
const uniqueUrls = [...new Set(discovered_urls)].slice(0, 50);

return [{ json: {
  page_id,
  url,
  domain_id,
  domain,
  success: true,
  status: 200,
  title,
  html_length: html.length,
  discovered_urls: uniqueUrls
}}];

// Get discovered URLs from Process Response (not from Update Page Status output)
let processData;
try {
  processData = $('Process Response').first().json;
} catch (e) {
  processData = { discovered_urls: [], domain_id: '', domain: '' };
}

const discovered_urls = processData.discovered_urls || [];
const domain_id = processData.domain_id || '';
const domain = processData.domain || '';

if (discovered_urls.length === 0) {
  return [{ json: { domain_id, domain, new_urls: 0 }}];
}

// Return each URL for insertion
return discovered_urls.map(url => ({ json: { domain_id, domain, url }}));

